void main() {
    var a = Point(1, 2);
    var b = Point(1, 2);
    print(a == b);   // false
}

class Point {
    final double x;
    final double y;
    const Point(this.x, this.y);

    @override
    bool operator ==(Object other) =>
            other is Point && x == other.x && y == other.y;

    @override
    int get hashCode => Object.hash(x, y);
}

void main() {
    var a = Point(1, 2);
    var b = Point(1, 2);
    print(a == b);   // true
}

